// Attempt 1: overloads — one signature per type, still no coverage for
// your custom types, and maintenance grows linearly
function first(xs: string[]): string;
function first(xs: number[]): number;
function first(xs: (string | number)[]): string | number;
function first(xs: unknown[]): unknown {
  return xs[0];
}

// Attempt 2: any — compiles, but the caller gets any back. All checking off.
function firstAny(xs: any[]): any { return xs[0]; }
const n = firstAny([1, 2, 3]);
n.toUpperCase();   // compiles — crashes at runtime 💥

// Attempt 3: unknown — honest, but forces every caller to narrow manually
function firstUn(xs: unknown[]): unknown { return xs[0]; }

function first<T>(xs: T[]): T {
  return xs[0];
}

const a = first(["x", "y"]);   // T = string → a: string
const b = first([1, 2, 3]);     // T = number → b: number
const c = first([1, "x"]);     // T = number | string

a.toUpperCase();   // ✓ — the compiler knows a is a string
b.toFixed(2);      // ✓ — and b is a number

// Function declaration
function identity<T>(value: T): T { return value; }

// Arrow function (note the trailing comma — required to disambiguate JSX)
const identity2 = <T,>(value: T): T => value;

// Method on an interface
interface Box<T> {
  value: T;
  map<R>(f: (value: T) => R): Box<R>;
}

// Type alias with a default (learn to read defaults in library code!)
type ApiResponse<T = unknown> = { status: number; data: T };

// Class
class Stack<T> {
  private items: T[] = [];
  push(item: T): void { this.items.push(item); }
  pop(): T | undefined { return this.items.pop(); }
}

function prop<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

interface Course { title: string; minutes: number }
const course: Course = { title: "Generics", minutes: 22 };

const t = prop(course, "title");    // T=Course, K="title" → t: string
const m = prop(course, "minutes");  // → m: number
prop(course, "titel");             // Error: "titel" isn't assignable to keyof Course
prop(course, "title".length);      // Error — nonsense argument rejected

// Without the constraint, .length is illegal — T could be anything
function logLength<T extends { length: number }>(x: T): T {
  console.log(x.length);   // ✓ every T has .length
  return x;
}

logLength("hello");      // T = "hello" (string literal)
logLength([1, 2, 3]);    // T = number[]
logLength(42);           // Error: number has no length — caught!

// Defaults make the parameter optional at the type level
type Paginated<T, Meta = { total: number; page: number }> = {
  items: T[];
  meta: Meta;
};

type Users = Paginated<User>;                        // default meta
type Custom = Paginated<User, { cursor: string }>;   // custom meta

// React: useState<S>(initial: S | (() => S)): [S, Dispatch<SetStateAction<S>>]
//   → S is captured from your initial value; the setter only accepts S or
//     an updater function. useState(0) gives you number state, guaranteed.

// Array.prototype.map in the lib: map<U>(callbackfn: (value: T, index: number, array: T[]) => U): U[]
//   → T flows in from the array, U is captured from your callback's return.
//     ["a","b"].map(s => s.length) → number[]. Zero annotations written.

// Promise.all: all<T extends readonly unknown[] | []>(values: T):
//   Awaited<{ [K in keyof T]: T[K] extends PromiseLike<infer U> ? U : T[K] }>
//   → tuple-aware: [Promise<User>, Promise<Order>] unwraps to [User, Order].
