// ✗ Generic-itis: T appears once, adds nothing, ceremony only
function printValue<T>(value: T): void {
  console.log(value);   // could just be (value: unknown): void
}

// ✗ Over-general: pretending we support anything when we don't
function fetchUser<T>(id: number): Promise<T> {
  // ...the body casts anyway; T is a lie callers chose
}

// ✓ Right-sized: the constraint documents the real contract
type Direction = "asc" | "desc";
function sortBy<T>(xs: T[], key: keyof T, dir: Direction = "asc"): T[] { /*...*/ return xs; }

