function groupBy<T, K extends string>(
  items: T[],
  keyOf: (item: T) => K
): Record<K, T[]> {
  const acc = {} as Record<K, T[]>;
  for (const item of items) {
    const key = keyOf(item);
    (acc[key] ??= []).push(item);
  }
  return acc;
}

interface Course { title: string; level: "Beginner" | "Intermediate" | "Advanced" }
const courses: Course[] = [
  { title: "Git", level: "Beginner" },
  { title: "TS", level: "Beginner" },
  { title: "React", level: "Intermediate" },
];

const byLevel = groupBy(courses, (c) => c.level);
// byLevel: Record<"Beginner" | "Intermediate" | "Advanced", Course[]>
byLevel.Beginner.length;      // 2 — autocomplete offers exactly the three levels
byLevel.Beginnar;             // Error — typo'd key caught at compile time
